(function(){
  if (window.__optInstalled__) return;
  window.__optInstalled__ = true;
  var canvas = document.getElementById('optCanvas');
  var ctx = canvas.getContext('2d');
  var iSlider = document.getElementById('iSlider');
  var iVal = document.getElementById('iVal');
  var hSlider = document.getElementById('hSlider');
  var hVal = document.getElementById('hVal');
  var out = document.getElementById('optOut');
  var modeBtn = document.getElementById('modeBtn');
  var playBtn = document.getElementById('playBtn');
  var D2R = Math.PI / 180;
  var mode = 'reflect';
  var running = false, pulse = 0;
  window.simState = { mode: 'reflect', i: 35, running: false };
  function line(x1, y1, x2, y2, color, width, dash){
    ctx.strokeStyle = color; ctx.lineWidth = width;
    ctx.setLineDash(dash || []);
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.setLineDash([]);
  }
  function pulseDot(poly, color){
    if (poly.length < 2) return;
    var plen = 0;
    for (var i = 1; i < poly.length; i++) plen += Math.sqrt(Math.pow(poly[i][0]-poly[i-1][0],2) + Math.pow(poly[i][1]-poly[i-1][1],2));
    var pos = ((pulse % 1) + 1) % 1 * plen;
    var acc = 0;
    for (var j = 1; j < poly.length; j++) {
      var seg = Math.sqrt(Math.pow(poly[j][0]-poly[j-1][0],2) + Math.pow(poly[j][1]-poly[j-1][1],2));
      if (acc + seg >= pos) {
        var t = seg ? (pos - acc) / seg : 0;
        var px = poly[j-1][0] + (poly[j][0]-poly[j-1][0]) * t;
        var py = poly[j-1][1] + (poly[j][1]-poly[j-1][1]) * t;
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(px, py, 4, 0, Math.PI * 2); ctx.fill();
        break;
      }
      acc += seg;
    }
  }
  function drawReflect(){
    var i = parseFloat(iSlider.value);
    var Y = 250, X = 360;
    line(60, Y, canvas.width - 60, Y, '#cbd5e1', 3);
    ctx.strokeStyle = '#7dd3fc'; ctx.lineWidth = 2;
    ctx.fillStyle = '#7dd3fc'; ctx.font = '12px sans-serif';
    ctx.beginPath(); ctx.moveTo(X, Y); ctx.lineTo(X, Y - 90); ctx.stroke();
    ctx.textAlign = 'left';
    ctx.fillText('العمود', X + 6, Y - 90);
    var srcX = X - 130 * Math.sin(i * D2R), srcY = Y - 130 * Math.cos(i * D2R);
    line(srcX, srcY, X, Y, '#facc15', 3);
    line(X, Y, X + 130 * Math.sin(i * D2R), Y - 130 * Math.cos(i * D2R), '#f87171', 3);
    ctx.fillStyle = '#facc15';
    ctx.textAlign = 'center';
    ctx.fillText('i = ' + i + '°', (srcX + X) / 2 - 20, srcY + 10);
    ctx.fillStyle = '#f87171';
    ctx.fillText('r = ' + i + '°', X + 30, Y - 60);
    out.textContent = 'زاوية السقوط i = ' + i + '° تساوي زاوية الانعكاس r = ' + i + '°';
    window.simState.i = i;
    if (running) pulseDot([[srcX, srcY], [X, Y], [X + 130 * Math.sin(i * D2R), Y - 130 * Math.cos(i * D2R)]], '#fff');
  }
  function drawPinhole(){
    var h = parseFloat(hSlider.value);
    var oX = 80, oY = 200, ph = 180, pHoleX = 360, scrX = 620;
    line(oX, oY, oX, oY - h, '#4ade80', 6);
    ctx.fillStyle = '#4ade80'; ctx.font = '12px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText('الجسم', oX - 40, oY + 8);
    line(pHoleX, 60, pHoleX, 320, '#64748b', 3);
    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('ثقب صغير', pHoleX, 54);
    line(scrX, 60, scrX, 320, '#7c3aed', 3);
    var tipY = oY - h;
    var tipImgY = ph + (ph - tipY) * ((scrX - pHoleX) / (pHoleX - oX));
    var baseImgY = ph + (ph - oY) * ((scrX - pHoleX) / (pHoleX - oX));
    line(oX, tipY, pHoleX, ph, '#facc15', 1.5);
    line(pHoleX, ph, scrX, tipImgY, '#facc15', 1.5);
    line(oX, oY, pHoleX, ph, '#facc15', 1.5);
    line(pHoleX, ph, scrX, baseImgY, '#facc15', 1.5);
    line(scrX, tipImgY, scrX, baseImgY, '#4ade80', 6);
    ctx.fillStyle = '#4ade80'; ctx.font = '12px sans-serif';
    ctx.textAlign = 'right'; ctx.textBaseline = 'alphabetic';
    ctx.fillText('صورة مقلوبة', scrX - 10, tipImgY - 10);
    out.textContent = 'الضوء ينتشر في خط مستقيم: صورة الجسم مقلوبة';
    if (running) pulseDot([[oX, tipY], [pHoleX, ph], [scrX, tipImgY]], '#fff');
  }
  function draw(){
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (mode === 'reflect') drawReflect(); else drawPinhole();
    hVal.textContent = hSlider.value;
    iVal.textContent = iSlider.value + '°';
  }
  modeBtn.addEventListener('click', function(){
    mode = mode === 'reflect' ? 'pinhole' : 'reflect';
    window.simState.mode = mode;
    modeBtn.textContent = mode === 'reflect' ? 'الكاميرا ذات الثقب' : 'قانون الانعكاس';
    out.textContent = mode === 'reflect' ? '' : 'الضوء ينتشر في خط مستقيم: صورة الجسم مقلوبة';
  });
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل النبضة';
  });
  iSlider.addEventListener('input', function(){});
  hSlider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){ if (running) pulse += 0.02; draw(); requestAnimationFrame(loop); }
  loop();
})();
